/// <summary>
/// 文档站组件（CodePreview、PropsTable……）的文案（同 vue-tsx-pro 的 docs-kit/messages.ts），挂在 <see cref="Lang"/> 上：改几条用 <c>Lang.ZhCn with { DocsKit = Lang.ZhCn.DocsKit with { … } }</c>。
/// </summary>
public sealed partial record DocsKitMessages
{
    /// <summary>CodePreview：预览区域的名称，默认“预览”</summary>
    public required string Preview { get; init; }

    /// <summary>CodePreview：显示源码的按钮，默认“显示代码”</summary>
    public required string ShowCode { get; init; }

    /// <summary>CodePreview：收起源码的按钮，默认“隐藏代码”</summary>
    public required string HideCode { get; init; }

    /// <summary>PropsTable：“名称”一列的表头，默认“名称”</summary>
    public required string Name { get; init; }

    /// <summary>PropsTable：“类型”一列的表头，默认“类型”</summary>
    public required string Type { get; init; }

    /// <summary>PropsTable：“默认值”一列的表头，默认“默认值”</summary>
    public required string DefaultValue { get; init; }

    /// <summary>PropsTable：“说明”一列的表头，默认“说明”</summary>
    public required string Description { get; init; }

    /// <summary>PropsTable：必填的 prop 的标记，默认“必填”</summary>
    public required string Required { get; init; }

    /// <summary>PropsTable：能 _bind 双向绑定的 prop 的标记，默认“可绑定”</summary>
    public required string Bindable { get; init; }

    /// <summary>简体中文（默认）。</summary>
    public static DocsKitMessages ZhCn => field ??= new()
    {
        Preview = "预览",
        ShowCode = "显示代码",
        HideCode = "隐藏代码",
        Name = "名称",
        Type = "类型",
        DefaultValue = "默认值",
        Description = "说明",
        Required = "必填",
        Bindable = "可绑定",
    };

    /// <summary>美国英语。</summary>
    public static DocsKitMessages EnUs => field ??= new()
    {
        Preview = "Preview",
        ShowCode = "Show code",
        HideCode = "Hide code",
        Name = "Name",
        Type = "Type",
        DefaultValue = "Default",
        Description = "Description",
        Required = "Required",
        Bindable = "Bindable",
    };
}
